import { useMemo, useState, type ReactNode } from 'react';
import Chart from 'react-apexcharts';
import type { ApexOptions } from 'apexcharts';
import { AlertCircle, AlertTriangle, BarChart3, Camera, CheckCircle2, ChevronLeft, ChevronRight, ClipboardCheck, Eye, FileImage, FileSpreadsheet, Gauge, Pencil, Plus, Printer, Save, Trash2, Wrench, X } from 'lucide-react';
import { auth } from '../../../core/firebase/firebaseConfig';
import { adminWriteRepository } from '../../shared/data/firestoreCollections';
import type { AppUser, LightVehicleMaintenance, LightVehicleWeeklyChecklist, Vehicle } from '../../shared/domain/models';
import { lightChecklistCategoryLabels, loadLightVehicleChecklistTopics, saveLightVehicleChecklistTopics, type LightChecklistTopic } from '../data/lightVehicleChecklistConfig';
import { ErrorBanner, MetricCard } from '../../shared/presentation/ui';

type Props = { vehicles: Vehicle[]; users: AppUser[]; checklists: LightVehicleWeeklyChecklist[]; maintenances: LightVehicleMaintenance[]; loading: boolean; onChanged: () => Promise<void>; initialTab?: 'checklist' | 'maintenance' };
type ItemStatus = LightVehicleWeeklyChecklist['items'][string];
const checklistCategories = ['A', 'B', 'C'] as const;

function formatDateInput(date: Date) { const year = date.getFullYear(); const month = String(date.getMonth() + 1).padStart(2, '0'); const day = String(date.getDate()).padStart(2, '0'); return `${year}-${month}-${day}`; }
function formatDateTimeInput(date: Date) { const datePart = formatDateInput(date); const hours = String(date.getHours()).padStart(2, '0'); const minutes = String(date.getMinutes()).padStart(2, '0'); return `${datePart}T${hours}:${minutes}`; }
function dateFromInput(value: string) { return new Date(`${value}T00:00:00`); }
function dateFromDateTimeInput(value: string) { return value ? new Date(value) : new Date(); }
function getMondayDateInput(value = formatDateInput(new Date())) { const date = dateFromInput(value); const day = date.getDay(); const diff = day === 0 ? -6 : 1 - day; date.setDate(date.getDate() + diff); return formatDateInput(date); }
function addDaysDateInput(value: string, days: number) { const date = dateFromInput(value || getMondayDateInput()); date.setDate(date.getDate() + days); return formatDateInput(date); }
function isDateInRange(value: string, start: string, end: string) { return (!start || value >= start) && (!end || value <= end); }
function checklistSortValue(checklist: LightVehicleWeeklyChecklist) { return checklist.checkedAt?.getTime() ?? dateFromInput(checklist.weekStart).getTime(); }
function latestChecklistByVehicle(checklists: LightVehicleWeeklyChecklist[]) { return checklists.reduce<Record<string, LightVehicleWeeklyChecklist>>((acc, item) => { const current = acc[item.vehicleId]; if (!current || checklistSortValue(item) > checklistSortValue(current)) acc[item.vehicleId] = item; return acc; }, {}); }

export function LightVehiclesPage({ vehicles, users, checklists, maintenances, loading, onChanged, initialTab = 'checklist' }: Props) {
  const lightVehicles = useMemo(() => vehicles.filter((vehicle) => vehicle.type === 'light_vehicle' && vehicle.status === 'active'), [vehicles]);
  const currentUser = users.find((user) => user.uid === auth.currentUser?.uid);
  const [error, setError] = useState(''); const [selectedVehicleId, setSelectedVehicleId] = useState(''); const [responsibleId, setResponsibleId] = useState('');
  const [weekStart, setWeekStart] = useState(() => getMondayDateInput()); const [checklistDateTime, setChecklistDateTime] = useState(() => formatDateTimeInput(new Date())); const [filterStart, setFilterStart] = useState(() => getMondayDateInput()); const [filterEnd, setFilterEnd] = useState(() => getMondayDateInput()); const [checklistKm, setChecklistKm] = useState(''); const [items, setItems] = useState<Record<string, ItemStatus>>({}); const [observations, setObservations] = useState(''); const [photoFiles, setPhotoFiles] = useState<File[]>([]);
  const [saving, setSaving] = useState(false); const [showForm, setShowForm] = useState(false); const [checklistView, setChecklistView] = useState<'records' | 'topics' | 'dashboard'>('records'); const [selectedChecklist, setSelectedChecklist] = useState<LightVehicleWeeklyChecklist | null>(null);
  const latestChecklistMap = useMemo(() => latestChecklistByVehicle(checklists), [checklists]); const currentWeekChecklists = checklists.filter((item) => item.weekStart === weekStart); const filteredChecklists = checklists.filter((item) => isDateInRange(item.weekStart, filterStart, filterEnd)); const maintenanceRows = maintenances.filter((item) => lightVehicles.some((vehicle) => vehicle.id === item.vehicleId)).map((item) => ({ ...item, currentKm: latestChecklistMap[item.vehicleId]?.kmAtual ?? 0 })); const overdue = maintenanceRows.filter((item) => item.currentKm >= item.nextRevisionKm).length; const upcoming = maintenanceRows.filter((item) => item.currentKm < item.nextRevisionKm && item.nextRevisionKm - item.currentKm <= 1000).length;
  void loading;

  function openChecklistForm() { const now = new Date(); const today = formatDateInput(now); setChecklistDateTime(formatDateTimeInput(now)); setWeekStart(getMondayDateInput(today)); setResponsibleId(currentUser?.uid ?? ''); setSelectedVehicleId(''); setChecklistKm(''); setItems({}); setObservations(''); setPhotoFiles([]); setError(''); setShowForm(true); }
  function chooseVehicle(id: string) { setSelectedVehicleId(id); const checklist = checklists.find((item) => item.vehicleId === id && item.weekStart === weekStart); setPhotoFiles([]); if (checklist) { setItems(checklist.items); setObservations(checklist.observations); setResponsibleId(checklist.responsibleId || currentUser?.uid || ''); setChecklistKm(checklist.kmAtual.toString()); setChecklistDateTime(formatDateTimeInput(checklist.checkedAt ?? new Date(`${checklist.weekStart}T08:00:00`))); } else { setItems({}); setObservations(''); setChecklistKm(''); setResponsibleId(currentUser?.uid ?? ''); } }
  function setChecklistDateTimeValue(value: string) { setChecklistDateTime(value); setWeekStart(getMondayDateInput(value.slice(0, 10))); setItems({}); }
  function setChecklistPhotos(fileList: FileList | null) { if (!fileList) return; const selected = Array.from(fileList).filter((file) => file.type.startsWith('image/')); if (selected.length !== fileList.length || photoFiles.length + selected.length > 3) setError('Anexe no máximo 3 imagens do ponto apresentado.'); setPhotoFiles((current) => [...current, ...selected].slice(0, 3)); }
  function removeChecklistPhoto(index: number) { setPhotoFiles((current) => current.filter((_, itemIndex) => itemIndex !== index)); }
  function shiftChecklistWeek(days: number) { const nextMonday = addDaysDateInput(getMondayDateInput(filterStart || weekStart), days); setWeekStart(nextMonday); setFilterStart(nextMonday); setFilterEnd(nextMonday); setItems({}); }
  function setChecklistWeekFilter(value: string) { const monday = getMondayDateInput(value); setWeekStart(monday); setFilterStart(monday); setFilterEnd(monday); setItems({}); }
  function setItemStatus(id: string, status: ItemStatus) { setItems((current) => { const next = { ...current }; if (current[id] === status) delete next[id]; else next[id] = status; return next; }); }
  async function saveChecklist() { const vehicle = lightVehicles.find((item) => item.id === selectedVehicleId); const responsible = users.find((item) => item.uid === (responsibleId || currentUser?.uid)); const kmAtual = Number(checklistKm); const checkedAt = dateFromDateTimeInput(checklistDateTime); const normalizedWeekStart = getMondayDateInput(formatDateInput(checkedAt)); if (!vehicle || !responsible || !Number.isFinite(kmAtual) || kmAtual < 0) { setError('Selecione o veículo e informe o KM atual. O responsável será preenchido pelo usuário logado.'); return; } setSaving(true); setError(''); try { await adminWriteRepository.saveLightVehicleWeeklyChecklist({ vehicleId: vehicle.id, vehiclePlate: vehicle.plate, vehicleFleet: vehicle.fleetNumber, responsibleId: responsible.uid, responsibleName: responsible.name, weekStart: normalizedWeekStart, checkedAt, kmAtual, items, status: Object.values(items).includes('not_ok') ? 'attention' : 'approved', observations, photoFiles }); const maintenance = maintenances.find((item) => item.vehicleId === vehicle.id); if (maintenance) { await adminWriteRepository.saveLightVehicleMaintenance({ id: maintenance.id, vehicleId: maintenance.vehicleId, vehiclePlate: maintenance.vehiclePlate, vehicleFleet: maintenance.vehicleFleet, currentKm: kmAtual, nextRevisionKm: maintenance.nextRevisionKm, notes: maintenance.notes }); } setWeekStart(normalizedWeekStart); setFilterStart(normalizedWeekStart); setFilterEnd(normalizedWeekStart); setPhotoFiles([]); setShowForm(false); await onChanged(); } catch (saveError) { setError(saveError instanceof Error ? saveError.message : 'Erro ao salvar checklist.'); } finally { setSaving(false); } }
  async function deleteChecklist(id: string) { const checklist = checklists.find((item) => item.id === id); if (!window.confirm('Deseja excluir este checklist semanal?')) return; setSaving(true); setError(''); try { await adminWriteRepository.deleteLightVehicleWeeklyChecklist(id); if (checklist) { const maintenance = maintenances.find((item) => item.vehicleId === checklist.vehicleId); if (maintenance) { const remainingLatest = latestChecklistByVehicle(checklists.filter((item) => item.id !== id && item.vehicleId === checklist.vehicleId))[checklist.vehicleId]; await adminWriteRepository.saveLightVehicleMaintenance({ id: maintenance.id, vehicleId: maintenance.vehicleId, vehiclePlate: maintenance.vehiclePlate, vehicleFleet: maintenance.vehicleFleet, currentKm: remainingLatest?.kmAtual ?? 0, nextRevisionKm: maintenance.nextRevisionKm, notes: maintenance.notes }); } } if (selectedChecklist?.id === id) setSelectedChecklist(null); await onChanged(); } catch (deleteError) { setError(deleteError instanceof Error ? deleteError.message : 'Erro ao excluir checklist.'); } finally { setSaving(false); } }
  async function saveMaintenanceRevision(vehicle: Vehicle, nextRevisionKm: number, notes: string) { const maintenance = maintenances.find((item) => item.vehicleId === vehicle.id); const latestChecklist = latestChecklistMap[vehicle.id]; const current = latestChecklist?.kmAtual ?? 0; if (!Number.isFinite(nextRevisionKm) || nextRevisionKm <= 0) { setError('Informe uma quilometragem válida para a próxima revisão.'); return; } setSaving(true); setError(''); try { await adminWriteRepository.saveLightVehicleMaintenance({ id: maintenance?.id ?? vehicle.id, vehicleId: vehicle.id, vehiclePlate: vehicle.plate, vehicleFleet: vehicle.fleetNumber, currentKm: current, nextRevisionKm, notes: notes || maintenance?.notes || '' }); await onChanged(); } catch (saveError) { setError(saveError instanceof Error ? saveError.message : 'Erro ao salvar revisão do veículo leve.'); } finally { setSaving(false); } }

return <div className="space-y-5"><ErrorBanner message={error} />{initialTab === 'checklist' ? <section className="ui-card overflow-hidden"><div className="flex flex-col gap-3 p-3 sm:p-4 xl:flex-row xl:items-center xl:justify-between"><nav aria-label="Navegacao do checklist de veiculos leves" className="flex w-full overflow-x-auto rounded-lg bg-zinc-50 p-1 xl:w-auto"><button className={`flex h-10 shrink-0 items-center justify-center gap-2 rounded-lg px-3 text-sm font-medium ${checklistView === 'records' ? 'bg-zinc-900 text-white' : 'text-zinc-600 hover:bg-zinc-100'}`} onClick={() => setChecklistView('records')} type="button"><ClipboardCheck size={16} />Checklist semanal</button><button className={`flex h-10 shrink-0 items-center justify-center gap-2 rounded-lg px-3 text-sm font-medium ${checklistView === 'topics' ? 'bg-zinc-900 text-white' : 'text-zinc-600 hover:bg-zinc-100'}`} onClick={() => setChecklistView('topics')} type="button"><Wrench size={16} />Gerenciar topicos</button><button className={`flex h-10 shrink-0 items-center justify-center gap-2 rounded-lg px-3 text-sm font-medium ${checklistView === 'dashboard' ? 'bg-zinc-900 text-white' : 'text-zinc-600 hover:bg-zinc-100'}`} onClick={() => setChecklistView('dashboard')} type="button"><BarChart3 size={16} />Dashboard e relatorios</button></nav>{checklistView === 'records' ? <div className="flex w-full flex-col gap-2 xl:w-auto xl:flex-row xl:items-center"><button className="ui-button h-10 justify-center gap-2 bg-avapex-yellow px-3 text-sm font-semibold text-avapex-black xl:w-auto" onClick={openChecklistForm} type="button"><Plus size={16} />Novo checklist</button><div className="grid w-full grid-cols-[40px_minmax(0,1fr)_40px] gap-2 xl:w-auto xl:grid-cols-[40px_160px_40px]"><button aria-label="Segunda-feira anterior" className="ui-icon-button h-10 w-full border-zinc-200 bg-white text-zinc-600" onClick={() => shiftChecklistWeek(-7)} title="Segunda-feira anterior" type="button"><ChevronLeft size={17} /></button><input aria-label="Semana do checklist" className="ui-input h-10 w-full min-w-0 px-2 text-sm sm:px-3" onChange={(event) => setChecklistWeekFilter(event.target.value)} title="Semana do checklist" type="date" value={filterStart} /><button aria-label="Próxima segunda-feira" className="ui-icon-button h-10 w-full border-zinc-200 bg-white text-zinc-600" onClick={() => shiftChecklistWeek(7)} title="Próxima segunda-feira" type="button"><ChevronRight size={17} /></button></div></div> : null}</div></section> : null}{initialTab === 'checklist' ? checklistView === 'topics' ? <ChecklistTopicsManager /> : checklistView === 'dashboard' ? <ChecklistDashboardReports checklists={checklists} lightVehicles={lightVehicles} /> : <><div className="grid gap-3 sm:grid-cols-3"><MetricCard icon={<Gauge size={18} />} label="Veículos leves ativos" value={lightVehicles.length} /><MetricCard icon={<CheckCircle2 size={18} />} label="Checklist da semana" value={`${new Set(currentWeekChecklists.map((item) => item.vehicleId)).size}/${lightVehicles.length}`} tone="success" /><MetricCard icon={<AlertTriangle size={18} />} label="Pendentes" value={Math.max(lightVehicles.length - new Set(currentWeekChecklists.map((item) => item.vehicleId)).size, 0)} tone="warning" /></div>{showForm ? <ChecklistForm checklistDateTime={checklistDateTime} checklistKm={checklistKm} items={items} lightVehicles={lightVehicles} observations={observations} onChooseVehicle={chooseVehicle} onRemovePhoto={removeChecklistPhoto} onSave={saveChecklist} onSetChecklistDateTime={setChecklistDateTimeValue} onSetChecklistKm={setChecklistKm} onSetItemStatus={setItemStatus} onSetObservations={setObservations} onSetPhotos={setChecklistPhotos} photoFiles={photoFiles} responsibleId={responsibleId} saving={saving} selectedVehicleId={selectedVehicleId} users={users} weekStart={weekStart} onClose={() => setShowForm(false)} /> : null}<ChecklistList checklists={filteredChecklists} onDelete={deleteChecklist} onSelect={setSelectedChecklist} />{selectedChecklist ? <ChecklistModal checklist={selectedChecklist} onClose={() => setSelectedChecklist(null)} /> : null}</> : <><div className="grid gap-3 sm:grid-cols-3"><MetricCard icon={<Wrench size={18} />} label="Revisões configuradas" value={maintenanceRows.length} /><MetricCard icon={<AlertTriangle size={18} />} label="Revisões vencidas" value={overdue} tone="danger" /><MetricCard icon={<Gauge size={18} />} label="Próximas até 1.000 km" value={upcoming} tone="warning" /></div><MaintenanceList checklists={checklists} lightVehicles={lightVehicles} maintenances={maintenanceRows} onSave={saveMaintenanceRevision} saving={saving} /></>}</div>;
}

function ChecklistForm({
  lightVehicles,
  users,
  selectedVehicleId,
  responsibleId,
  weekStart,
  checklistDateTime,
  checklistKm,
  observations,
  photoFiles,
  items,
  saving,
  onChooseVehicle,
  onSetChecklistDateTime,
  onSetChecklistKm,
  onSetObservations,
  onSetPhotos,
  onRemovePhoto,
  onSetItemStatus,
  onSave,
  onClose,
}: {
  lightVehicles: Vehicle[];
  users: AppUser[];
  selectedVehicleId: string;
  responsibleId: string;
  weekStart: string;
  checklistDateTime: string;
  checklistKm: string;
  observations: string;
  photoFiles: File[];
  items: Record<string, ItemStatus>;
  saving: boolean;
  onChooseVehicle: (id: string) => void;
  onSetChecklistDateTime: (value: string) => void;
  onSetChecklistKm: (value: string) => void;
  onSetObservations: (value: string) => void;
  onSetPhotos: (files: FileList | null) => void;
  onRemovePhoto: (index: number) => void;
  onSetItemStatus: (id: string, status: ItemStatus) => void;
  onSave: () => void;
  onClose: () => void;
}) {
  const responsible = users.find((user) => user.uid === responsibleId);
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/45 p-2 sm:p-4"><section className="flex max-h-[96vh] w-full max-w-3xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl"><header className="flex shrink-0 items-start justify-between gap-3 border-b border-zinc-200 px-4 py-3 sm:px-5"><div><p className="text-xs font-semibold uppercase text-zinc-500">Veículos leves</p><h2 className="mt-1 text-lg font-semibold text-zinc-950">Novo checklist semanal</h2><p className="mt-1 text-sm text-zinc-500">Preencha os dados e marque cada tópico.</p></div><button aria-label="Fechar novo checklist" className="ui-icon-button h-10 w-10 shrink-0 border-zinc-200" onClick={onClose} type="button"><X size={18} /></button></header><div className="min-h-0 overflow-y-auto p-4 sm:p-5"><div className="rounded-lg border border-zinc-200 bg-zinc-50 p-3 sm:p-4"><div className="grid gap-3 sm:grid-cols-2"><Field label="Veículo / frota"><select className="ui-input h-11 w-full bg-white px-3" onChange={(event) => onChooseVehicle(event.target.value)} value={selectedVehicleId}><option value="">Selecione</option>{lightVehicles.map((vehicle) => <option key={vehicle.id} value={vehicle.id}>{vehicle.plate} - {vehicle.fleetNumber}</option>)}</select></Field><Field label="Responsável"><input className="ui-input h-11 w-full bg-white px-3 text-zinc-700" readOnly value={responsible?.name ?? 'Usuário logado'} /></Field><Field label="Data e hora do checklist"><input className="ui-input h-11 w-full bg-white px-3" onChange={(event) => onSetChecklistDateTime(event.target.value)} type="datetime-local" value={checklistDateTime} /><span className="mt-1 block text-xs text-zinc-500">Semana de referência: {weekStart}</span></Field><Field label="KM atual"><input className="ui-input h-11 w-full bg-white px-3" min="0" onChange={(event) => onSetChecklistKm(event.target.value)} type="number" value={checklistKm} /></Field></div></div><div className="mt-5 space-y-5">{checklistCategories.map((category) => <div key={category}><div className="mb-2 flex items-center gap-2"><span className="rounded-md bg-zinc-900 px-2 py-1 text-xs font-bold text-white">{category}</span><h3 className="text-sm font-semibold">{lightChecklistCategoryLabels[category]}</h3></div><div className="grid gap-2 md:grid-cols-2">{loadLightVehicleChecklistTopics().filter((topic) => topic.category === category).map((topic) => <div className="flex flex-col gap-2 rounded-lg border border-zinc-200 p-3 sm:flex-row sm:items-center sm:justify-between" key={topic.id}><span className="text-sm leading-5 text-zinc-800">{topic.label}</span><div className="flex shrink-0 flex-wrap gap-1"><MarkButton active={items[topic.id] === 'ok'} label="C" onClick={() => onSetItemStatus(topic.id, 'ok')} /><MarkButton active={items[topic.id] === 'not_ok'} label="N" onClick={() => onSetItemStatus(topic.id, 'not_ok')} /><MarkButton active={items[topic.id] === 'na'} label="N/A" onClick={() => onSetItemStatus(topic.id, 'na')} /></div></div>)}</div></div>)}</div><Field label="Observações e avarias"><textarea className="ui-input min-h-24 w-full bg-white px-3 py-2" onChange={(event) => onSetObservations(event.target.value)} placeholder="Descreva avarias ou pendências" value={observations} /></Field><div className="mt-3 rounded-lg border border-dashed border-zinc-300 bg-zinc-50 p-3"><div className="grid gap-2 sm:grid-cols-2"><label className={`flex cursor-pointer items-center justify-center gap-2 rounded-lg px-4 py-4 text-center text-sm font-semibold shadow-sm ${photoFiles.length >= 3 ? 'bg-zinc-100 text-zinc-400' : 'bg-avapex-yellow text-avapex-black'}`}><Camera size={18} /><span>Tirar foto agora</span><input accept="image/*" capture="environment" className="sr-only" disabled={photoFiles.length >= 3} onChange={(event) => { onSetPhotos(event.target.files); event.currentTarget.value = ''; }} type="file" /></label><label className={`flex cursor-pointer items-center justify-center gap-2 rounded-lg border px-4 py-4 text-center text-sm font-semibold shadow-sm ${photoFiles.length >= 3 ? 'border-zinc-200 bg-zinc-100 text-zinc-400' : 'border-zinc-200 bg-white text-zinc-700'}`}><FileImage size={18} /><span>Buscar na galeria</span><input accept="image/*" className="sr-only" disabled={photoFiles.length >= 3} multiple onChange={(event) => { onSetPhotos(event.target.files); event.currentTarget.value = ''; }} type="file" /></label></div><p className="mt-2 text-xs text-zinc-500">Opcional. Use até 3 fotos para registrar o ponto descrito. No celular, o primeiro botão abre a câmera e o segundo busca imagens já salvas.</p>{photoFiles.length ? <div className="mt-3 grid gap-2">{photoFiles.map((file, index) => <div className="flex items-center justify-between gap-3 rounded-md border border-zinc-200 bg-white px-3 py-2 text-sm" key={`${file.name}-${index}`}><span className="min-w-0 truncate">{file.name}</span><button aria-label={`Remover imagem ${file.name}`} className="ui-icon-button h-8 w-8 shrink-0 border-transparent text-red-600 hover:bg-red-50" onClick={() => onRemovePhoto(index)} title="Remover imagem" type="button"><Trash2 size={15} /></button></div>)}</div> : null}</div></div><footer className="flex shrink-0 flex-col-reverse gap-2 border-t border-zinc-200 bg-white p-3 sm:flex-row sm:justify-end sm:p-4"><button className="ui-button h-11 border border-zinc-200 bg-white px-4 text-sm" onClick={onClose} type="button">Cancelar</button><button className="ui-button h-11 gap-2 bg-avapex-yellow px-4 text-sm font-semibold text-avapex-black disabled:opacity-50" disabled={saving} onClick={onSave} type="button"><Save size={16} />Salvar checklist</button></footer></section></div>;
}

function ChecklistList({ checklists, onSelect, onDelete }: { checklists: LightVehicleWeeklyChecklist[]; onSelect: (item: LightVehicleWeeklyChecklist) => void; onDelete: (id: string) => void }) { return <section className="ui-card overflow-hidden"><div className="border-b border-zinc-200 px-4 py-3"><h3 className="font-semibold">Checklists registrados</h3></div><div className="overflow-x-auto"><table className="ui-table min-w-[720px]"><thead><tr><th>Veículo</th><th>Responsável</th><th>Data</th><th>Status</th><th>Ação</th></tr></thead><tbody>{checklists.map((item) => <tr key={item.id}><td className="font-semibold">{item.vehiclePlate} <span className="text-xs text-zinc-500">{item.vehicleFleet}</span></td><td>{item.responsibleName}</td><td>{item.checkedAt ? item.checkedAt.toLocaleString('pt-BR') : item.weekStart}</td><td><ChecklistStatusBadge status={item.status} /></td><td><div className="flex items-center gap-2"><button aria-label="Visualizar checklist" className="ui-icon-button h-9 w-9 border-zinc-200" onClick={() => onSelect(item)} title="Visualizar checklist" type="button"><Eye size={16} /></button><button aria-label="Excluir checklist" className="ui-icon-button h-9 w-9 border-red-100 text-red-600 hover:bg-red-50" onClick={() => onDelete(item.id)} title="Excluir checklist" type="button"><Trash2 size={16} /></button></div></td></tr>)}</tbody></table></div></section>; }
function ChecklistStatusBadge({ status }: { status: LightVehicleWeeklyChecklist['status'] }) { if (status === 'attention') return <span className="inline-flex items-center gap-1 rounded-full bg-amber-50 px-2.5 py-1 text-xs font-semibold text-amber-700"><AlertTriangle size={14} />Atenção</span>; if (status === 'pending') return <span className="inline-flex items-center gap-1 rounded-full bg-zinc-100 px-2.5 py-1 text-xs font-semibold text-zinc-600"><AlertCircle size={14} />Pendente</span>; return <span className="inline-flex items-center gap-1 rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-700"><CheckCircle2 size={14} />Conforme</span>; }

function ChecklistModal({ checklist, onClose }: { checklist: LightVehicleWeeklyChecklist; onClose: () => void }) { return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/45 p-4"><section className="flex max-h-[94vh] w-full max-w-3xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl"><header className="flex flex-col gap-3 border-b border-zinc-200 p-4 sm:flex-row sm:items-start sm:justify-between"><div><h2 className="font-semibold">Checklist semanal</h2><p className="mt-1 text-sm text-zinc-500">{checklist.vehiclePlate} - {checklist.vehicleFleet} · {checklist.weekStart}</p></div><div className="flex flex-wrap gap-2"><button className="ui-button h-9 gap-2 border border-zinc-200 bg-white px-3 text-sm" onClick={() => printChecklistPdf(checklist)} type="button"><Printer size={15} />Imprimir PDF</button><button className="ui-button h-9 gap-2 border border-zinc-200 bg-white px-3 text-sm" onClick={() => exportChecklistExcel(checklist)} type="button"><FileSpreadsheet size={15} />Exportar Excel</button><button aria-label="Fechar" className="ui-icon-button h-9 w-9" onClick={onClose} type="button"><X size={17} /></button></div></header><div className="overflow-y-auto p-4"><p className="text-sm"><strong>Responsável:</strong> {checklist.responsibleName} · <strong>KM atual:</strong> {checklist.kmAtual.toLocaleString("pt-BR")}</p><div className="mt-4 space-y-2">{loadLightVehicleChecklistTopics().map((topic) => <div className="flex items-center justify-between border-b border-zinc-100 py-2 text-sm" key={topic.id}><span>{topic.label}</span><span className="font-semibold">{formatChecklistMark(checklist.items[topic.id])}</span></div>)}</div><div className="mt-5"><h3 className="text-sm font-semibold">Observações e avarias</h3><p className="mt-1 whitespace-pre-wrap text-sm text-zinc-700">{checklist.observations || 'Nenhuma observação registrada.'}</p></div>{checklist.photoUrls.length ? <div className="mt-5"><h3 className="text-sm font-semibold">Registros fotográficos</h3><div className="mt-2 grid gap-2 sm:grid-cols-3">{checklist.photoUrls.map((url, index) => <a className="block overflow-hidden rounded-lg border border-zinc-200 bg-zinc-50" href={url} key={url} rel="noreferrer" target="_blank"><img alt={`Registro fotográfico ${index + 1}`} className="h-36 w-full object-cover" src={url} /></a>)}</div></div> : null}</div></section></div>; }

function MaintenanceList({ lightVehicles, maintenances, checklists, saving, onSave }: { lightVehicles: Vehicle[]; maintenances: LightVehicleMaintenance[]; checklists: LightVehicleWeeklyChecklist[]; saving: boolean; onSave: (vehicle: Vehicle, nextRevisionKm: number, notes: string) => Promise<void> }) { const latestMap = latestChecklistByVehicle(checklists); const [editingId, setEditingId] = useState(''); const [nextKm, setNextKm] = useState(''); const [editNotes, setEditNotes] = useState(''); function startEdit(vehicle: Vehicle, item?: LightVehicleMaintenance) { setEditingId(vehicle.id); setNextKm(item?.nextRevisionKm.toString() ?? ''); setEditNotes(item?.notes ?? ''); } async function submit(vehicle: Vehicle) { await onSave(vehicle, Number(nextKm), editNotes); setEditingId(''); setNextKm(''); setEditNotes(''); } return <section className="ui-card overflow-hidden"><div className="flex flex-col gap-3 border-b border-zinc-200 px-4 py-3 sm:flex-row sm:items-center sm:justify-between"><div><h3 className="font-semibold">Acompanhamento da frota leve</h3><p className="mt-1 text-sm text-zinc-500">Edite apenas a próxima revisão. O KM atual é atualizado pelo checklist semanal.</p></div><button className="ui-button h-10 justify-center gap-2 border border-zinc-200 bg-white px-3 text-sm text-zinc-700" onClick={() => printMaintenancePdf(lightVehicles, maintenances, checklists)} type="button"><Printer size={16} />Imprimir PDF</button></div><div className="overflow-x-auto"><table className="ui-table min-w-[920px]"><thead><tr><th>Veículo</th><th>Km atual</th><th>Próxima revisão</th><th>Saldo</th><th>Status</th><th>Ação</th></tr></thead><tbody>{lightVehicles.map((vehicle) => { const item = maintenances.find((maintenance) => maintenance.vehicleId === vehicle.id); const latestChecklist = latestMap[vehicle.id]; const current = item ? latestChecklist?.kmAtual ?? 0 : null; const balance = item && current !== null ? item.nextRevisionKm - current : null; const editing = editingId === vehicle.id; return <tr key={vehicle.id}><td className="font-semibold">{vehicle.plate} <span className="text-xs text-zinc-500">{vehicle.fleetNumber}</span></td><td>{current !== null ? <span>{current.toLocaleString('pt-BR')} {latestChecklist ? <span className="text-xs text-zinc-500">checklist</span> : <span className="text-xs text-zinc-500">sem checklist</span>}</span> : '-'}</td><td>{editing ? <input aria-label="Próxima revisão" className="ui-input h-9 w-32 px-2 text-sm" min="1" onChange={(event) => setNextKm(event.target.value)} type="number" value={nextKm} /> : item?.nextRevisionKm.toLocaleString('pt-BR') ?? '-'}</td><td>{balance === null ? '-' : `${balance.toLocaleString('pt-BR')} km`}</td><td><MaintenanceStatusBadge balance={balance} hasMaintenance={Boolean(item)} /></td><td>{editing ? <div className="flex gap-2"><button className="ui-button h-9 gap-2 bg-avapex-yellow px-3 text-sm font-semibold text-avapex-black disabled:opacity-50" disabled={saving} onClick={() => void submit(vehicle)} type="button"><Save size={15} />Salvar</button><button className="ui-button h-9 border border-zinc-200 bg-white px-3 text-sm" disabled={saving} onClick={() => setEditingId('')} type="button">Cancelar</button></div> : <button className="ui-button h-9 gap-2 border border-zinc-200 bg-white px-3 text-sm text-zinc-700" onClick={() => startEdit(vehicle, item)} type="button"><Pencil size={15} />Editar</button>}</td></tr>; })}</tbody></table></div></section>; }
function MaintenanceStatusBadge({ balance, hasMaintenance }: { balance: number | null; hasMaintenance: boolean }) { if (!hasMaintenance) return <span className="inline-flex items-center gap-1 rounded-full bg-zinc-100 px-2.5 py-1 text-xs font-semibold text-zinc-600"><AlertCircle size={14} />Sem revisão</span>; if (balance !== null && balance <= 0) return <span className="inline-flex items-center gap-1 rounded-full bg-red-50 px-2.5 py-1 text-xs font-semibold text-red-700"><AlertTriangle size={14} />Vencida</span>; if (balance !== null && balance <= 1000) return <span className="inline-flex items-center gap-1 rounded-full bg-amber-50 px-2.5 py-1 text-xs font-semibold text-amber-700"><Gauge size={14} />Próxima</span>; return <span className="inline-flex items-center gap-1 rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-semibold text-emerald-700"><CheckCircle2 size={14} />Em dia</span>; }
function maintenanceStatusLabel(balance: number | null, hasMaintenance: boolean) { if (!hasMaintenance) return 'Sem revisao'; if (balance !== null && balance <= 0) return 'Vencida'; if (balance !== null && balance <= 1000) return 'Proxima'; return 'Em dia'; }
function Field({ label, children }: { label: string; children: ReactNode }) { return <label className="mt-4 block"><span className="mb-2 block text-sm font-medium text-zinc-700">{label}</span>{children}</label>; }
function MarkButton({ active, label, onClick }: { active: boolean; label: string; onClick: () => void }) { return <button className={`min-w-9 rounded-md border px-2 py-1 text-xs font-bold ${active ? 'border-zinc-900 bg-zinc-900 text-white' : 'border-zinc-200 bg-white text-zinc-600 hover:border-zinc-400'}`} onClick={onClick} type="button">{label}</button>; }
function formatChecklistMark(status?: ItemStatus) { if (status === 'ok') return 'C'; if (status === 'not_ok') return 'N'; if (status === 'na') return 'N/A'; return '-'; }
function escapeHtml(value: unknown) { return String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;'); }
function checklistFileName(checklist: LightVehicleWeeklyChecklist, extension: string) { return `checklist-${checklist.vehiclePlate}-${checklist.weekStart}`.replace(/[^a-z0-9-]+/gi, '-').toLowerCase() + extension; }
function exportChecklistExcel(checklist: LightVehicleWeeklyChecklist) {
  const topics = loadLightVehicleChecklistTopics();
  const rows = checklistCategories.flatMap((category) => topics.filter((topic) => topic.category === category).map((topic) => `<tr><td>${category}</td><td>${escapeHtml(lightChecklistCategoryLabels[category])}</td><td>${escapeHtml(topic.label)}</td><td>${formatChecklistMark(checklist.items[topic.id])}</td></tr>`));
  const html = `<html><head><meta charset="utf-8" /></head><body><table><tr><th colspan="4">Checklist semanal - veiculo leve</th></tr><tr><td>Veiculo</td><td colspan="3">${escapeHtml(checklist.vehiclePlate)} - ${escapeHtml(checklist.vehicleFleet)}</td></tr><tr><td>Responsavel</td><td colspan="3">${escapeHtml(checklist.responsibleName)}</td></tr><tr><td>Dia do checklist</td><td colspan="3">${escapeHtml(checklist.weekStart)}</td></tr><tr><td>KM atual</td><td colspan="3">${checklist.kmAtual}</td></tr><tr><td>Observacoes</td><td colspan="3">${escapeHtml(checklist.observations || 'Nenhuma observacao registrada.')}</td></tr><tr><th>Categoria</th><th>Descricao da categoria</th><th>Topico</th><th>Marcacao</th></tr>${rows.join('')}</table></body></html>`;
  const url = URL.createObjectURL(new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = checklistFileName(checklist, '.xls');
  link.click();
  URL.revokeObjectURL(url);
}
function printChecklistPdf(checklist: LightVehicleWeeklyChecklist) {
  const topics = loadLightVehicleChecklistTopics();
  const grouped = checklistCategories.map((category) => `<section class="category"><div class="category-title"><strong>Categoria ${category}</strong><span>${escapeHtml(lightChecklistCategoryLabels[category])}</span></div><table><thead><tr><th>Topico</th><th>C</th><th>N</th><th>N/A</th></tr></thead><tbody>${topics.filter((topic) => topic.category === category).map((topic) => { const mark = formatChecklistMark(checklist.items[topic.id]); return `<tr><td>${escapeHtml(topic.label)}</td><td>${mark === 'C' ? 'X' : ''}</td><td>${mark === 'N' ? 'X' : ''}</td><td>${mark === 'N/A' ? 'X' : ''}</td></tr>`; }).join('')}</tbody></table></section>`).join('');
  const photos = checklist.photoUrls.length ? `<section class="photos"><h2>Registros fotograficos</h2><div class="photo-grid">${checklist.photoUrls.map((url, index) => `<figure><img src="${escapeHtml(url)}" alt="Registro fotografico ${index + 1}" /><figcaption>Imagem ${index + 1}</figcaption></figure>`).join('')}</div></section>` : '';
  const html = `<!doctype html><html><head><meta charset="utf-8" /><title>Checklist ${escapeHtml(checklist.vehiclePlate)}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{margin:0;background:#fff;color:#18181b;font-family:Arial,sans-serif;font-size:12px}.page{position:relative;min-height:267mm;padding:18mm 14mm 14mm;overflow:hidden}.page:before{content:"";position:absolute;inset:0;background:url('/checklist-pdf-background.png') right 14mm bottom 12mm/60% auto no-repeat;opacity:.12;z-index:0}.content{position:relative;z-index:1}.brand{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;border-bottom:2px solid #f3c400;padding-bottom:12px}.brand img{width:170px;height:auto}.title{text-align:right}.title h1{margin:0;font-size:22px}.title p{margin:5px 0 0;color:#52525b}.info{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:18px 0;padding:12px;border:1px solid #d4d4d8;border-radius:8px;background:rgba(255,255,255,.86)}.info div{min-height:36px}.label{display:block;color:#71717a;font-size:10px;text-transform:uppercase}.value{display:block;margin-top:3px;font-weight:700}.category{break-inside:avoid;margin-top:12px}.category-title{display:flex;align-items:center;gap:8px;margin-bottom:6px}.category-title strong{background:#18181b;color:#fff;border-radius:5px;padding:5px 8px}.category-title span{font-weight:700}table{width:100%;border-collapse:collapse;background:rgba(255,255,255,.92)}th,td{border:1px solid #d4d4d8;padding:7px 8px;text-align:left;vertical-align:middle}th{background:#f4f4f5;font-size:10px;text-transform:uppercase}td:nth-child(n+2),th:nth-child(n+2){width:42px;text-align:center;font-weight:700}.notes,.photos{margin-top:14px;border:1px solid #d4d4d8;border-radius:8px;padding:10px;background:rgba(255,255,255,.9);break-inside:avoid}.notes h2,.photos h2{margin:0 0 8px;font-size:13px}.notes p{margin:0;white-space:pre-wrap}.photo-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.photo-grid figure{margin:0}.photo-grid img{width:100%;height:120px;object-fit:cover;border:1px solid #d4d4d8;border-radius:6px}.photo-grid figcaption{margin-top:4px;color:#71717a;font-size:10px;text-align:center}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:28px}.line{border-top:1px solid #18181b;padding-top:6px;text-align:center;font-size:11px}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{padding:0}.no-print{display:none}}</style></head><body><main class="page"><div class="content"><header class="brand"><img src="/checklist-pdf-logo.png" alt="AVAPEX Transportes" /><div class="title"><h1>Checklist semanal</h1><p>Veiculo leve</p></div></header><section class="info"><div><span class="label">Veiculo / placa</span><span class="value">${escapeHtml(checklist.vehiclePlate)}</span></div><div><span class="label">Frota</span><span class="value">${escapeHtml(checklist.vehicleFleet)}</span></div><div><span class="label">Responsavel</span><span class="value">${escapeHtml(checklist.responsibleName)}</span></div><div><span class="label">Dia do checklist</span><span class="value">${escapeHtml(checklist.weekStart)}</span></div><div><span class="label">KM atual</span><span class="value">${checklist.kmAtual.toLocaleString('pt-BR')}</span></div><div><span class="label">Status</span><span class="value">${checklist.status === 'attention' ? 'Atencao' : 'Conforme'}</span></div></section>${grouped}<section class="notes"><h2>Observacoes e avarias</h2><p>${escapeHtml(checklist.observations || 'Nenhuma observacao registrada.')}</p></section>${photos}<section class="signatures"><div class="line">Responsavel pelo checklist</div><div class="line">Conferencia</div></section></div></main><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),300));</script></body></html>`;
  const printWindow = window.open('', '_blank', 'width=900,height=1200');
  if (!printWindow) return;
  printWindow.document.open();
  printWindow.document.write(html);
  printWindow.document.close();
}
function printMaintenancePdf(lightVehicles: Vehicle[], maintenances: LightVehicleMaintenance[], checklists: LightVehicleWeeklyChecklist[]) {
  const latestMap = latestChecklistByVehicle(checklists);
  const exportedAt = new Date();
  const exportedAtLabel = exportedAt.toLocaleString('pt-BR');
  const rows = lightVehicles.map((vehicle) => { const item = maintenances.find((maintenance) => maintenance.vehicleId === vehicle.id); const latestChecklist = latestMap[vehicle.id]; const current = item ? latestChecklist?.kmAtual ?? 0 : null; const balance = item && current !== null ? item.nextRevisionKm - current : null; return { vehicle, item, current, balance, latestChecklist }; });
  const tableRows = rows.map(({ vehicle, item, current, balance, latestChecklist }) => `<tr><td><strong>${escapeHtml(vehicle.plate)}</strong><br/><span>${escapeHtml(vehicle.fleetNumber)}</span></td><td>${current !== null ? current.toLocaleString('pt-BR') : '-'}</td><td>${latestChecklist ? escapeHtml(latestChecklist.weekStart) : '-'}</td><td>${item ? item.nextRevisionKm.toLocaleString('pt-BR') : '-'}</td><td>${balance === null ? '-' : `${balance.toLocaleString('pt-BR')} km`}</td><td class="status ${!item ? 'muted' : balance !== null && balance <= 0 ? 'danger' : balance !== null && balance <= 1000 ? 'warning' : 'success'}">${maintenanceStatusLabel(balance, Boolean(item))}</td></tr>`).join('');
  const html = `<!doctype html><html><head><meta charset="utf-8" /><title>Revisoes por km</title><style>@page{size:A4 landscape;margin:12mm}*{box-sizing:border-box}body{margin:0;background:#fff;color:#18181b;font-family:Arial,sans-serif;font-size:11px}.page{position:relative;min-height:186mm;padding:14mm 12mm 12mm;overflow:hidden}.page:before{content:"";position:absolute;inset:0;background:url('/checklist-pdf-background.png') right 12mm bottom 10mm/45% auto no-repeat;opacity:.10;z-index:0}.content{position:relative;z-index:1}.brand{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;border-bottom:2px solid #f3c400;padding-bottom:10px}.brand img{width:165px;height:auto}.title{text-align:right}.title h1{margin:0;font-size:21px}.title p{margin:5px 0 0;color:#52525b}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:14px 0}.box{border:1px solid #d4d4d8;border-radius:8px;background:rgba(255,255,255,.9);padding:9px}.label{display:block;color:#71717a;font-size:9px;text-transform:uppercase}.value{display:block;margin-top:3px;font-size:14px;font-weight:700}table{width:100%;border-collapse:collapse;background:rgba(255,255,255,.94)}th,td{border:1px solid #d4d4d8;padding:7px 8px;text-align:left;vertical-align:middle}th{background:#f4f4f5;font-size:9px;text-transform:uppercase}td span{color:#71717a;font-size:10px}.status{border-radius:999px;font-weight:700;text-align:center}.status.success{color:#047857;background:#ecfdf5}.status.warning{color:#b45309;background:#fffbeb}.status.danger{color:#b91c1c;background:#fef2f2}.status.muted{color:#52525b;background:#f4f4f5}.footer{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:26px}.line{border-top:1px solid #18181b;padding-top:6px;text-align:center;font-size:11px}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{padding:0}}</style></head><body><main class="page"><div class="content"><header class="brand"><img src="/checklist-pdf-logo.png" alt="AVAPEX Transportes" /><div class="title"><h1>Revisoes por km</h1><p>Exportado em ${escapeHtml(exportedAtLabel)}</p></div></header><section class="summary"><div class="box"><span class="label">Veiculos</span><span class="value">${lightVehicles.length}</span></div><div class="box"><span class="label">Configuradas</span><span class="value">${rows.filter((row) => row.item).length}</span></div><div class="box"><span class="label">Vencidas</span><span class="value">${rows.filter((row) => row.item && row.balance !== null && row.balance <= 0).length}</span></div><div class="box"><span class="label">Proximas ate 1.000 km</span><span class="value">${rows.filter((row) => row.item && row.balance !== null && row.balance > 0 && row.balance <= 1000).length}</span></div></section><table><thead><tr><th>Veiculo / frota</th><th>KM atual</th><th>Ultimo checklist</th><th>Proxima revisao</th><th>Saldo</th><th>Status</th></tr></thead><tbody>${tableRows}</tbody></table><section class="footer"><div class="line">Assinatura do responsavel</div><div class="line">Data: ____/____/________</div></section></div></main><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),300));</script></body></html>`;
  const printWindow = window.open('', '_blank', 'width=1200,height=900');
  if (!printWindow) return;
  printWindow.document.open();
  printWindow.document.write(html);
  printWindow.document.close();
}
function excelSheetName(value: string) { return value.replace(/[[\]:*?/\\]/g, '-').slice(0, 31) || 'Checklist'; }
function xmlEscape(value: unknown) { return String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&apos;'); }
function checklistRowsForExport(checklist: LightVehicleWeeklyChecklist) {
  const topics = loadLightVehicleChecklistTopics();
  return checklistCategories.flatMap((category) => topics.filter((topic) => topic.category === category).map((topic) => ({ category, categoryLabel: lightChecklistCategoryLabels[category], topic: topic.label, mark: formatChecklistMark(checklist.items[topic.id]) })));
}
function exportChecklistWorkbook(checklists: LightVehicleWeeklyChecklist[], reportWeek: string) {
  const worksheets = checklists.map((checklist) => `<Worksheet ss:Name="${xmlEscape(excelSheetName(checklist.vehiclePlate))}"><Table><Row><Cell ss:MergeAcross="3"><Data ss:Type="String">Checklist semanal - ${xmlEscape(checklist.vehiclePlate)}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Veiculo</Data></Cell><Cell ss:MergeAcross="2"><Data ss:Type="String">${xmlEscape(checklist.vehiclePlate)} - ${xmlEscape(checklist.vehicleFleet)}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Responsavel</Data></Cell><Cell ss:MergeAcross="2"><Data ss:Type="String">${xmlEscape(checklist.responsibleName)}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Segunda-feira</Data></Cell><Cell ss:MergeAcross="2"><Data ss:Type="String">${xmlEscape(checklist.weekStart)}</Data></Cell></Row><Row><Cell><Data ss:Type="String">KM atual</Data></Cell><Cell ss:MergeAcross="2"><Data ss:Type="Number">${checklist.kmAtual}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Observacoes</Data></Cell><Cell ss:MergeAcross="2"><Data ss:Type="String">${xmlEscape(checklist.observations || 'Nenhuma observacao registrada.')}</Data></Cell></Row><Row><Cell><Data ss:Type="String">Categoria</Data></Cell><Cell><Data ss:Type="String">Descricao da categoria</Data></Cell><Cell><Data ss:Type="String">Topico</Data></Cell><Cell><Data ss:Type="String">Marcacao</Data></Cell></Row>${checklistRowsForExport(checklist).map((row) => `<Row><Cell><Data ss:Type="String">${row.category}</Data></Cell><Cell><Data ss:Type="String">${xmlEscape(row.categoryLabel)}</Data></Cell><Cell><Data ss:Type="String">${xmlEscape(row.topic)}</Data></Cell><Cell><Data ss:Type="String">${row.mark}</Data></Cell></Row>`).join('')}</Table></Worksheet>`);
  const xml = `<?xml version="1.0" encoding="UTF-8"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">${worksheets.join('')}</Workbook>`;
  const url = URL.createObjectURL(new Blob([xml], { type: 'application/vnd.ms-excel;charset=utf-8' }));
  const link = document.createElement('a');
  link.href = url;
  link.download = `relatorio-checklists-${reportWeek}.xls`;
  link.click();
  URL.revokeObjectURL(url);
}
function printChecklistReport(checklists: LightVehicleWeeklyChecklist[], reportWeek: string) {
  const pages = checklists.map((checklist) => `<section class="page"><div class="content"><header class="brand"><img src="/checklist-pdf-logo.png" alt="AVAPEX Transportes" /><div class="title"><h1>Relatorio semanal</h1><p>${xmlEscape(reportWeek)} · ${xmlEscape(checklist.vehiclePlate)}</p></div></header><section class="info"><div><span class="label">Veiculo / placa</span><span class="value">${xmlEscape(checklist.vehiclePlate)}</span></div><div><span class="label">Frota</span><span class="value">${xmlEscape(checklist.vehicleFleet)}</span></div><div><span class="label">Responsavel</span><span class="value">${xmlEscape(checklist.responsibleName)}</span></div><div><span class="label">KM atual</span><span class="value">${checklist.kmAtual.toLocaleString('pt-BR')}</span></div></section>${checklistCategories.map((category) => `<section class="category"><div class="category-title"><strong>${category}</strong><span>${xmlEscape(lightChecklistCategoryLabels[category])}</span></div><table><thead><tr><th>Topico</th><th>C</th><th>N</th><th>N/A</th></tr></thead><tbody>${checklistRowsForExport(checklist).filter((row) => row.category === category).map((row) => `<tr><td>${xmlEscape(row.topic)}</td><td>${row.mark === 'C' ? 'X' : ''}</td><td>${row.mark === 'N' ? 'X' : ''}</td><td>${row.mark === 'N/A' ? 'X' : ''}</td></tr>`).join('')}</tbody></table></section>`).join('')}<section class="notes"><h2>Observacoes e avarias</h2><p>${xmlEscape(checklist.observations || 'Nenhuma observacao registrada.')}</p></section></div></section>`).join('');
  const html = `<!doctype html><html><head><meta charset="utf-8" /><title>Relatorio ${xmlEscape(reportWeek)}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{margin:0;background:#fff;color:#18181b;font-family:Arial,sans-serif;font-size:12px}.page{position:relative;min-height:267mm;padding:18mm 14mm 14mm;break-after:page;overflow:hidden}.page:before{content:"";position:absolute;inset:0;background:url('/checklist-pdf-background.png') right 14mm bottom 12mm/60% auto no-repeat;opacity:.12;z-index:0}.content{position:relative;z-index:1}.brand{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;border-bottom:2px solid #f3c400;padding-bottom:12px}.brand img{width:170px;height:auto}.title{text-align:right}.title h1{margin:0;font-size:22px}.title p{margin:5px 0 0;color:#52525b}.info{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:18px 0;padding:12px;border:1px solid #d4d4d8;border-radius:8px;background:rgba(255,255,255,.86)}.label{display:block;color:#71717a;font-size:10px;text-transform:uppercase}.value{display:block;margin-top:3px;font-weight:700}.category{break-inside:avoid;margin-top:12px}.category-title{display:flex;align-items:center;gap:8px;margin-bottom:6px}.category-title strong{background:#18181b;color:#fff;border-radius:5px;padding:5px 8px}.category-title span{font-weight:700}table{width:100%;border-collapse:collapse;background:rgba(255,255,255,.92)}th,td{border:1px solid #d4d4d8;padding:7px 8px;text-align:left;vertical-align:middle}th{background:#f4f4f5;font-size:10px;text-transform:uppercase}td:nth-child(n+2),th:nth-child(n+2){width:42px;text-align:center;font-weight:700}.notes{margin-top:14px;border:1px solid #d4d4d8;border-radius:8px;padding:10px;background:rgba(255,255,255,.9)}.notes h2{margin:0 0 8px;font-size:13px}.notes p{margin:0;white-space:pre-wrap}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{padding:0}}</style></head><body>${pages}<script>window.addEventListener('load',()=>setTimeout(()=>window.print(),300));</script></body></html>`;
  const printWindow = window.open('', '_blank', 'width=900,height=1200');
  if (!printWindow) return;
  printWindow.document.open();
  printWindow.document.write(html);
  printWindow.document.close();
}

function ChecklistDashboardReports({ checklists, lightVehicles }: { checklists: LightVehicleWeeklyChecklist[]; lightVehicles: Vehicle[] }) {
  const [reportWeek, setReportWeek] = useState(() => getMondayDateInput());
  const [dashboardStart, setDashboardStart] = useState(() => addDaysDateInput(getMondayDateInput(), -28));
  const [dashboardEnd, setDashboardEnd] = useState(() => getMondayDateInput());
  const [selectedVehicleIds, setSelectedVehicleIds] = useState<string[]>([]);
  const dashboardRows = useMemo(() => checklists.filter((item) => isDateInRange(item.weekStart, dashboardStart, dashboardEnd)), [checklists, dashboardEnd, dashboardStart]);
  const weekRows = checklists.filter((item) => item.weekStart === reportWeek);
  const selectedRows = weekRows.filter((item) => selectedVehicleIds.includes(item.vehicleId));
  const weeklyData = useMemo(() => Object.entries(dashboardRows.reduce<Record<string, number>>((acc, item) => { acc[item.weekStart] = (acc[item.weekStart] ?? 0) + 1; return acc; }, {})).sort(([left], [right]) => left.localeCompare(right)), [dashboardRows]);
  const vehicleData = useMemo(() => lightVehicles.map((vehicle) => ({ label: vehicle.plate, count: dashboardRows.filter((item) => item.vehicleId === vehicle.id).length })).filter((item) => item.count > 0).sort((left, right) => right.count - left.count), [dashboardRows, lightVehicles]);
  const lineOptions: ApexOptions = { chart: { toolbar: { show: false }, zoom: { enabled: false } }, colors: ['#f3c400'], dataLabels: { enabled: false }, stroke: { curve: 'smooth', width: 3 }, xaxis: { categories: weeklyData.map(([date]) => date) }, yaxis: { min: 0, forceNiceScale: true }, grid: { borderColor: '#e4e4e7' } };
  const barOptions: ApexOptions = { chart: { toolbar: { show: false } }, colors: ['#18181b'], dataLabels: { enabled: false }, plotOptions: { bar: { borderRadius: 4, horizontal: true } }, xaxis: { categories: vehicleData.map((item) => item.label) }, grid: { borderColor: '#e4e4e7' } };
  function toggleVehicle(id: string) { setSelectedVehicleIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); }
  function selectAllWeekVehicles() { setSelectedVehicleIds(weekRows.map((item) => item.vehicleId)); }
  function shiftReportWeek(days: number) { setReportWeek((current) => addDaysDateInput(getMondayDateInput(current), days)); setSelectedVehicleIds([]); }
  return <div className="space-y-5"><section className="ui-card overflow-hidden"><div className="flex flex-col gap-3 p-3 sm:p-4 lg:flex-row lg:items-center lg:justify-between"><div><h2 className="font-semibold text-zinc-950">Dashboard e relatórios</h2><p className="mt-1 text-sm text-zinc-500">Acompanhe os checklists por período e gere relatórios por segunda-feira.</p></div><div className="grid w-full grid-cols-2 gap-2 sm:w-auto sm:grid-cols-[150px_150px]"><input aria-label="Inicio do dashboard" className="ui-input h-10 min-w-0 px-2 text-sm sm:px-3" onChange={(event) => setDashboardStart(event.target.value)} title="Início" type="date" value={dashboardStart} /><input aria-label="Fim do dashboard" className="ui-input h-10 min-w-0 px-2 text-sm sm:px-3" onChange={(event) => setDashboardEnd(event.target.value)} title="Fim" type="date" value={dashboardEnd} /></div></div></section><div className="grid gap-3 sm:grid-cols-3"><MetricCard icon={<ClipboardCheck size={18} />} label="Checklists no período" value={dashboardRows.length} tone="info" /><MetricCard icon={<CheckCircle2 size={18} />} label="Veículos no período" value={new Set(dashboardRows.map((item) => item.vehicleId)).size} tone="success" /><MetricCard icon={<AlertTriangle size={18} />} label="Com não conformidade" value={dashboardRows.filter((item) => item.status === 'attention').length} tone="warning" /></div><div className="grid gap-4 xl:grid-cols-2"><section className="ui-card p-4 sm:p-5"><h2 className="font-semibold text-zinc-950">Checklists por segunda-feira</h2><div className="mt-4 min-h-[260px]">{weeklyData.length ? <Chart height={260} options={lineOptions} series={[{ name: 'Checklists', data: weeklyData.map(([, count]) => count) }]} type="line" /> : <p className="py-10 text-sm text-zinc-500">Nenhum checklist registrado no período.</p>}</div></section><section className="ui-card p-4 sm:p-5"><h2 className="font-semibold text-zinc-950">Checklists realizados por veículo</h2><div className="mt-4 min-h-[260px]">{vehicleData.length ? <Chart height={260} options={barOptions} series={[{ name: 'Checklists', data: vehicleData.map((item) => item.count) }]} type="bar" /> : <p className="py-10 text-sm text-zinc-500">Nenhum veículo com checklist no período.</p>}</div></section></div><section className="ui-card overflow-hidden"><header className="flex flex-col gap-3 border-b border-zinc-200 px-4 py-4 sm:px-5 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-xs font-semibold uppercase text-zinc-500">Relatórios</p><h2 className="mt-1 font-semibold text-zinc-950">Imprimir checklist por segunda-feira</h2><p className="mt-1 text-sm text-zinc-500">Escolha a segunda-feira e marque os veículos que entram no relatório.</p></div><div className="grid w-full grid-cols-[88px_minmax(0,1fr)] gap-2 sm:w-auto sm:grid-cols-[88px_150px_auto]"><div className="grid grid-cols-2 gap-2"><button aria-label="Segunda-feira anterior do relatório" className="ui-icon-button h-10 w-full border-zinc-200 bg-white text-zinc-600" onClick={() => shiftReportWeek(-7)} title="Segunda-feira anterior" type="button"><ChevronLeft size={17} /></button><button aria-label="Próxima segunda-feira do relatório" className="ui-icon-button h-10 w-full border-zinc-200 bg-white text-zinc-600" onClick={() => shiftReportWeek(7)} title="Próxima segunda-feira" type="button"><ChevronRight size={17} /></button></div><input aria-label="Segunda-feira do relatório" className="ui-input h-10 min-w-0 px-2 text-sm sm:px-3" onChange={(event) => { setReportWeek(getMondayDateInput(event.target.value)); setSelectedVehicleIds([]); }} type="date" value={reportWeek} /><button className="ui-button col-span-2 h-10 justify-center border border-zinc-200 bg-white px-3 text-sm text-zinc-700 sm:col-span-1" onClick={selectAllWeekVehicles} type="button">Selecionar todos</button></div></header><div className="p-4 sm:p-5"><div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{weekRows.map((item) => <label className={`flex cursor-pointer items-center gap-3 rounded-lg border px-3 py-3 ${selectedVehicleIds.includes(item.vehicleId) ? 'border-zinc-900 bg-zinc-50' : 'border-zinc-200 bg-white'}`} key={item.id}><input checked={selectedVehicleIds.includes(item.vehicleId)} onChange={() => toggleVehicle(item.vehicleId)} type="checkbox" /><span><strong className="block text-sm">{item.vehiclePlate}</strong><span className="text-xs text-zinc-500">{item.vehicleFleet} · {item.responsibleName}</span></span></label>)}{!weekRows.length ? <p className="rounded-lg border border-dashed border-zinc-300 p-4 text-sm text-zinc-500">Nenhum checklist encontrado para esta segunda-feira.</p> : null}</div><div className="mt-4 grid gap-2 sm:flex sm:justify-end"><button className="ui-button h-10 justify-center gap-2 border border-zinc-200 bg-white px-3 text-sm text-zinc-700 disabled:opacity-50" disabled={!selectedRows.length} onClick={() => printChecklistReport(selectedRows, reportWeek)} type="button"><Printer size={16} />Imprimir selecionados</button><button className="ui-button h-10 justify-center gap-2 bg-avapex-yellow px-3 text-sm font-semibold text-avapex-black disabled:opacity-50" disabled={!selectedRows.length} onClick={() => exportChecklistWorkbook(selectedRows, reportWeek)} type="button"><FileSpreadsheet size={16} />Exportar Excel</button></div></div></section></div>;
}

function ChecklistTopicsManager() {
  const [topics, setTopics] = useState<LightChecklistTopic[]>(() => loadLightVehicleChecklistTopics());
  const [category, setCategory] = useState<LightChecklistTopic['category']>('A');
  const [newTopic, setNewTopic] = useState('');
  const selectedTopics = topics.filter((topic) => topic.category === category);
  function addTopic() { const label = newTopic.trim(); if (!label || topics.some((topic) => topic.label.toLowerCase() === label.toLowerCase())) return; const next = [...topics, { id: `custom_${Date.now()}`, label, category }]; setTopics(next); saveLightVehicleChecklistTopics(next); setNewTopic(''); }
  function removeTopic(id: string) { const next = topics.filter((topic) => topic.id !== id); setTopics(next); saveLightVehicleChecklistTopics(next); }
return <div className="space-y-4"><section className="ui-card overflow-hidden"><header className="border-b border-zinc-200 px-4 py-4 sm:px-5"><p className="text-xs font-semibold uppercase text-zinc-500">Configuração</p><h2 className="mt-1 text-base font-semibold text-zinc-950">Modelo do checklist semanal</h2><p className="mt-1 text-sm text-zinc-500">Defina as categorias e os itens que aparecerão nos próximos checklists.</p></header><div className="px-4 py-4 sm:px-5"><p className="text-sm font-semibold text-zinc-900">Categorias do checklist</p><p className="mt-1 text-xs text-zinc-500">Selecione A, B ou C para editar os itens.</p><div className="mt-3 flex flex-wrap gap-2">{(['A', 'B', 'C'] as const).map((group) => <button className={`h-9 min-w-12 rounded-lg border px-4 text-sm font-semibold ${category === group ? 'border-zinc-900 bg-zinc-900 text-white' : 'border-zinc-200 bg-white text-zinc-700 hover:border-zinc-400'}`} key={group} onClick={() => { setCategory(group); setNewTopic(''); }} type="button">{group}</button>)}</div></div></section><section className="ui-card overflow-hidden"><header className="flex items-start justify-between gap-3 border-b border-zinc-200 px-4 py-4 sm:px-5"><div><p className="text-xs font-semibold uppercase text-zinc-500">Categoria selecionada</p><h3 className="mt-1 text-base font-semibold text-zinc-950">Categoria {category}</h3><p className="mt-1 text-sm text-zinc-500">{lightChecklistCategoryLabels[category]}</p></div><span className="rounded-full bg-zinc-100 px-3 py-1 text-xs font-semibold text-zinc-600">{selectedTopics.length} itens</span></header><div className="p-4 sm:p-5"><div className="flex flex-col gap-2 sm:flex-row"><input className="ui-input h-11 min-w-0 flex-1 px-3 text-sm" onChange={(event) => setNewTopic(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') addTopic(); }} placeholder="Adicionar novo item à categoria" value={newTopic} /><button className="ui-button h-11 gap-2 bg-avapex-yellow px-4 text-sm font-semibold text-avapex-black" onClick={addTopic} type="button"><Plus size={16} />Adicionar item</button></div><div className="mt-4 space-y-2">{selectedTopics.map((topic) => <div className="flex min-h-12 items-center justify-between gap-3 rounded-lg border border-zinc-200 bg-white px-3 py-2.5" key={topic.id}><span className="text-sm leading-5 text-zinc-800">{topic.label}</span><button aria-label={`Remover tópico ${topic.label}`} className="ui-icon-button h-9 w-9 shrink-0 border-transparent text-zinc-500 hover:border-red-200 hover:bg-red-50 hover:text-red-600" onClick={() => removeTopic(topic.id)} title="Remover tópico" type="button"><Trash2 size={16} /></button></div>)}{selectedTopics.length === 0 ? <p className="rounded-lg border border-dashed border-zinc-300 p-3 text-sm text-zinc-500">Nenhum tópico nesta categoria.</p> : null}</div></div></section></div>;
}






